```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    // Specify the file name and word to search for
    const string filename = "input.txt";
    const string search_word = "example";

    // Create a map to store word counts
    unordered_map<string, int> word_counts;

    // Open the input file
    ifstream input_file(filename);
    if (!input_file.is_open()) {
        cout << "Failed to open file: " << filename << endl;
        return 1;
    }

    // Read the file line by line and update word counts
    string line;
    while (getline(input_file, line)) {
        // Split the line into words
        size_t start = 0;
        size_t end = line.find(' ');
        while (end != string::npos) {
            string word = line.substr(start, end - start);
            start = end + 1;
            end = line.find(' ', start);

            // Increment the count for the search word
            if (word == search_word) {
                word_counts[search_word]++;
            }
        }
        // Handle the last word in the line
        string word = line.substr(start);
        if (word == search_word) {
            word_counts[search_word]++;
        }
    }

    // Close the input file
    input_file.close();

    // Print the word count
    if (word_counts.find(search_word) != word_counts.end()) {
        cout << "Number of occurrences of '" << search_word << "': " << word_counts[search_word] << endl;
    } else {
        cout << "Word '" << search_word << "' not found in file." << endl;
    }

    return 0;
}
```

This program reads the input file `input.txt` line by line, splits each line into words, and increments the count for the specified search word `search_word`. The word counts are stored in an `unordered_map` data structure.

Note that this program assumes that the input file contains words separated by spaces. If your input file uses different delimiters, you'll need to modify the code accordingly.

Also, this program doesn't handle cases where the search word appears as a part of a larger word (e.g., "exampled" would not match "example"). If you need to handle partial word matches, you'll need to modify the code to use a more complex search algorithm (such as regular expressions or a more sophisticated string comparison approach).
